<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';$user=require_login();ensure_lead_schema();require_once __DIR__.'/settlement-workflow.php';sales_settlement_schema();$error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();try{$id=sales_settlement_close($user,$_POST);flash('success','Η εκκαθάριση κλειδώθηκε. Δεν έγινε τραπεζική πληρωμή.');redirect_to('settlements.php?id='.$id);}catch(Throwable $e){$error=$e instanceof InvalidArgumentException?$e->getMessage():'Η εκκαθάριση δεν αποθηκεύτηκε.';}
}
$id=is_string($_GET['id']??null)?$_GET['id']:'';$rows=[];$batch=null;
if($id!==''){try{[$batch,$rows]=sales_settlement_read($user,$id);}catch(InvalidArgumentException){http_response_code(404);exit('Δεν βρέθηκε διαθέσιμη εκκαθάριση.');}}
if(isset($_GET['csv'])&&$batch){header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="melas-settlement-'.$batch['period_month'].'.csv"');$out=fopen('php://output','wb');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['Περίοδος','Δικαιούχος','Email','Χειρισμός','Τύπος προμήθειας','Κωδικός εγγραφής','Ημερομηνία δικαιώματος','Κλειδωμένο ποσό','Προθεσμία','Τρέχουσα κατάσταση','Ημερομηνία καταβολής','Αναφορά καταβολής'],',','"','');foreach($rows as $r)fputcsv($out,array_map('sales_csv_cell',[$batch['period_month'],$r['name'],$r['email'],sales_settlement_relationship($r['relationship']),$r['source_type'],$r['source_id'],$r['earned_at'],$r['amount'],$r['due_on'],$r['current_status'],$r['payout_date'],$r['payout_reference']]),',','"','');fclose($out);exit;}
render_header('Μηνιαίες εκκαθαρίσεις',$user);
?>
