<?php if(can_view_all_sales_financials($user)): ?><form method="post" class="stack"><?= csrf_field() ?><label>Κλεισμένος ημερολογιακός μήνας<input type="month" name="period_month" required max="<?= e((new DateTimeImmutable('first day of last month'))->format('Y-m')) ?>"></label><label>Νωρίτερη υποχρεωτική προθεσμία (αν υπάρχει)<input type="date" name="earlier_due_on"></label><label>Σημείωση λογιστηρίου<textarea name="note" required minlength="10" maxlength="2000"></textarea></label><label class="checkbox-row"><input type="checkbox" name="reviewed" value="1" required> Ελέγχθηκαν οι πληρωτέες αμοιβές, οι σχέσεις και οι προθεσμίες. Δεν δηλώνω ότι πληρώθηκαν.</label><label>Ο κωδικός μου<input type="password" name="actor_password" required autocomplete="current-password"></label><button class="button primary">Κλείδωμα νέας εκκαθάρισης</button></form><p>Συμπληρωματική εκκαθάριση του ίδιου μήνα επιτρέπεται για αμοιβές που δεν είχαν συμπεριληφθεί. Κάθε δικαίωμα μπαίνει μόνο μία φορά. Παλαιότερα ασυμπερίληπτα ποσά μεταφέρονται χωρίς αλλαγή της αρχικής γένεσης.</p><?php endif; ?></section>
<?php if($batch): ?><section class="card form-section"><h2><?= e($batch['period_month']) ?> · έως <?= e($batch['due_on']) ?></h2><p><?= e($batch['note']) ?></p><a class="button" href="<?= e(crm_url('settlements.php?id='.$batch['id'].'&csv=1')) ?>">CSV λογιστηρίου — επιτρεπόμενα στοιχεία</a><div class="table-wrap"><table><thead><tr><th>Δικαιούχος</th><th>Χειρισμός</th><th>Ποσό κλειδώματος</th><th>Προθεσμία εγγραφής</th><th>Εξόφληση</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['name']) ?></td><td><?= e(sales_settlement_relationship($r['relationship'])) ?></td><td>€<?= e($r['amount']) ?></td><td><?= e($r['due_on']) ?></td><td><?= e($r['current_status']==='paid'?'Πληρωμένο '.$r['payout_date']:($r['due_on']<date('Y-m-d')?'Εκπρόθεσμο / προς έλεγχο':'Εκκρεμεί')) ?><?php if($r['current_status']==='cancelled'): ?> · Ακύρωση στην αρχική εγγραφή — απαιτείται λογιστική συμφωνία<?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><p>Τα κλειδωμένα ποσά είναι ιστορικό στιγμιότυπο. Η τρέχουσα εξόφληση διαβάζεται από τις αρχικές προμήθειες και δεν ξανακαταχωρίζεται εδώ.</p></section><?php endif; ?>
